head.script:
scwin.onpageload = function() {
};

scwin.onpageunload = function() {
};

scwin.ibx_openPopup_onclick = function(e) {
	requires("uiplugin.popup");
	var opts = {
		"id" : "popup_sub1",
		"type" : "wframePopup",
		"width" : "300px",
		"height" : "200px",
		"top" : 100,
		"left" : 100,
		"popupName" : "popup_sub1",
		"modal" : true,
		"useIFrame" : true,
		"title" : "popup_sub1",
		"disableCloseButton" : false,    // Close 버튼은 보이고 동작만 안하게 하는 설정
		"useControl" : true,             // controls 옵션이 동작하려면 true로 설정
		"controls" : { "minimize" : true, "maximize" : true, "close" : true },
		"processMsgFrame" : true,
		"windowDragMove" : true
	};
	$p.openPopup("popup_openPopup_modal_WESD-982_(WSQ-5324)_sub1.xml", opts);
};

scwin.checkVal = function() {
	return WebSquare.wUnit.getDomById('_modal').style.display == 'none';
}
scwin.unitTest = function() {
	//Unit
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('ibx_openPopup').click()");
	WebSquare.wUnit.addCommand("pause", "400");			

	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('popup_sub1_wframe_ibx_openPopup').click()");
	WebSquare.wUnit.addCommand("pause", "400");	

	WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
	WebSquare.wUnit.addCommand("pause", "500");
	//Run test and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}	
scwin.unitTest()
